 CONSTRAINT "UQ_ForumInteractiveSession_Post_User_Attempt" UNIQUE ("InteractivePostID", "UserID", "AttemptNumber"),
 CONSTRAINT "CK_ForumInteractiveSession_State_JSON" CHECK ("SessionStateJSON" IS NULL OR ("SessionStateJSON") IS JSON)
);

