 "DigestCadence" VARCHAR(30) NOT NULL DEFAULT 'Daily Digest',
 "OpenToPeerMentoring" BOOLEAN NOT NULL DEFAULT FALSE,
 "__mj_CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 "__mj_UpdatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
